namespace CrimsonDraft.Operators.Appearance
{
    /// <summary>Interchangeable equipment slots of the soldier mesh (see Soldier_Appearance_Variants.md).</summary>
    public enum SoldierAppearanceSlot
    {
        Helmet   = 0,
        Glasses  = 1,
        Backpack = 2,
        Vest     = 3,
        Mask     = 4, // spec-ops masks (gas mask, respirator, shemagh...): no piece in the source FBX
    }

    /// <summary>
    /// Body types: blend shapes with these exact names on the body and on every accessory
    /// (generated by Tools/Blender/soldier_bodyshapes.py), so gear follows the body. Weights 0..100.
    /// </summary>
    public enum SoldierBodyShape
    {
        Female   = 0,
        Heavy    = 1,
        Muscular = 2,
        Thin     = 3,
    }

    public static class SoldierAppearanceVariants
    {
        public const int   BodyShapeCount = 4;
        /// <summary>Height is a uniform scale of the model (clips key every bone, so proportions can't change).</summary>
        public const float MinHeight = 0.9f;
        public const float MaxHeight = 1.1f;

        public const int    SlotCount = 5;
        /// <summary>Selecting this hides every variant of the slot (no mesh needed).</summary>
        public const string None      = "None";
        public const string Default   = "Default";

        /// <summary>Face gear has Fit_* blend shapes (Depth / Height / Size sliders) to sit right on the face.</summary>
        public static bool SupportsFit(SoldierAppearanceSlot slot) =>
            slot == SoldierAppearanceSlot.Glasses || slot == SoldierAppearanceSlot.Mask;

        /// <summary>What a slot shows when nothing was chosen: the original piece, or nothing for Mask.</summary>
        public static string DefaultVariant(SoldierAppearanceSlot slot) =>
            slot == SoldierAppearanceSlot.Mask ? None : Default;
    }
}
